import { html , render , WebComponent , customElement , attr , attrState , state, css, ViewTemplate, ViewContext, asyncAppend, repeat, children } from '@lithium-framework/core';
import '@lithium-framework/router-element';
import { json } from 'stream/consumers';
import 'unofficial-pf-v5-wc';
import 'unofficial-pf-v5-wc-icons';

@customElement({
  name: 'page-informations',
  template: html`${(information: Information) => {
    return html`<pf-page masterhead-no-icon masterhead-no-branding drawer-inline drawer-expanded drawer-static drawer-panel-left >
    <div slot = "drawer-panel">
      <pf-navigation>
        <pf-navigation-list>
            <pf-navigation-list-item
              @mousedown=${() => { window.location.href = "cours" }}>
                Cours
            </pf-navigation-list-item>
            <pf-navigation-list-item
              @mousedown=${() => { window.location.href = "informations" }}>
                Informations supplémentaires
            </pf-navigation-list-item>
            <pf-navigation-list-item
              @mousedown=${() => { window.location.href = "compte" }}>
                Compte
            </pf-navigation-list-item>
            <pf-navigation-list-item
              @mousedown=${() => { window.location.href = "profile" }}>
                Profile
            </pf-navigation-list-item>
        </pf-navigation-list>
      </pf-navigation>
    </div>
    <div>
      <pf-panel header scrollable>
        <h1 slot = "header" >Informations</h1>
        <div class="table-infos">
                                ${asyncAppend(information.preloadData(), (result) => {
                                    console.log(result)
                                    return html`
                                    <div class="raw-infos">
                                        ${
                                            repeat(
                                                result, 
                                                html`${(cour) => {
                                                    return html`
                                                        <div class="row"">
                                                            <div class="type-de-cours">${cour.type_cours}</div>
                                                            <div class="heure-debut">${cour.heure_debut}</div>
                                                            <div class="heure-fin">${cour.heure_fin}</div>
                                                        </div>`;
                                                }}`
                                            )
                                        }
                                    </div>
                                    `;
                                })}
                            </div>
      </pf-panel>
    </div>
    <pf-avatar></pf-avatar>
  </pf-page>`
  }}`
})
export class Information extends WebComponent{
  data: any = []
  async preloadData(): Promise<any[]> {
    try {
        // Récupérer userData du localStorage
        const userDataString = localStorage.getItem('userData');

        // Vérifier si userData est présent dans le localStorage
        if (!userDataString) {
            throw new Error('Utilisateur non connecté. Aucune donnée dans localStorage.');
        }

        // Parser les données stockées sous forme de chaîne de caractères
        const userData = JSON.parse(userDataString);
        console.log(userData);

        // Envoi de la requête avec les données utilisateur
        const response = await fetch('http://localhost:3000/infos', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(userData), // Convertir les données en chaîne JSON
        });

        // Vérifier si la requête a réussi
        if (!response.ok) {
            throw new Error('Erreur serveur.');
        }

        // Extraire les données de la réponse
        const data = await response.json();
        console.log(data);
        
        // Retourner les données si elles sont présentes
        return data.length > 0 ? data : [];
    } catch (error) {
        console.error('Erreur lors de la requête fetch:', error);
        return [];
    }
  }

}


let template: ViewTemplate<any> = html`${( context:ViewContext )=>{


  return html`<page-informations></page-informations>`;

}}`




render(template);